package com.raaz.assistant.features

import android.app.Activity
import android.app.Application
import androidx.lifecycle.AndroidViewModel
import androidx.lifecycle.viewModelScope
import com.raaz.assistant.mcp.*
import kotlinx.coroutines.*
import kotlinx.coroutines.flow.*
import org.json.JSONObject
import java.util.UUID

data class HubState(val tasks:List<AgentTask> = emptyList(),val memory:List<MemoryItem> = emptyList(),val apps:List<InstalledApp> = emptyList(),val contacts:List<DeviceContact> = emptyList(),val servers:List<McpServer> = emptyList(),val tools:Map<String,List<McpTool>> = emptyMap(),val connection:Map<String,String> = emptyMap(),val flags:Map<String,Boolean> = emptyMap(),val wakeKey:Boolean=false,val selected:DeviceContact?=null,val busy:Boolean=false,val error:String?=null,val notice:String?=null)
class HubViewModel(app:Application):AndroidViewModel(app) {
 val store=FeatureStore(app);private val mcp=McpClient();private var visible=false;private var foreground=false;private var execution:Job?=null;private var executingName:String?=null;private var executingSource:String?=null;private val probes=mutableMapOf<String,Job>();private val probeEpoch=mutableMapOf<String,String>()
 private val contactGate=LatestRequestGate();private var contactJob:Job?=null
 private val mutable=MutableStateFlow(HubState());val state=mutable.asStateFlow()
 private val flagNames=listOf("memory_enabled","memory_cloud","assistant_tools","direct_calls","delegate_recognition","automation_com.google.android.youtube","automation_com.android.chrome")
 init{viewModelScope.launch{try{withContext(Dispatchers.IO){store.recoverInterrupted()};refresh()}catch(e:Exception){fail("Feature data could not be loaded. Existing data was preserved.")};while(isActive){delay(1500);if(visible||foreground)refresh()}}}
 fun foreground(value:Boolean){foreground=value;if(value&&androidx.core.content.ContextCompat.checkSelfPermission(getApplication(),android.Manifest.permission.READ_CONTACTS)!=android.content.pm.PackageManager.PERMISSION_GRANTED){contactGate.invalidate();contactJob?.cancel();mutable.update{it.copy(contacts=emptyList())}}}
 fun onBackground(){if(executingName !in setOf("scroll_app","back_app"))execution?.cancel()}
 fun visible(value:Boolean){visible=value;if(value)viewModelScope.launch{refresh()}}
 suspend fun refresh(){try{val snapshot=withContext(Dispatchers.IO){Triple(store.tasks(),store.memories(),readServers(store))};var selectionError=false;val selected=try{store.selectedRecipient()}catch(e:Exception){selectionError=true;null};mutable.update{it.copy(tasks=snapshot.first,memory=snapshot.second,servers=snapshot.third,flags=flagNames.associateWith{f->store.flag(f)},wakeKey=store.secretPresent("porcupine"),selected=selected,error=if(selectionError)"Saved recipient could not be read. Clear it in Contacts; other data was preserved." else it.error)}}catch(e:Exception){if(e is CancellationException)throw e;fail("Feature settings or database could not be read. Existing data was preserved.")}}
 fun fail(message:String){mutable.update{it.copy(error=message.take(500),busy=false)}}
 private fun notice(message:String){mutable.update{it.copy(notice=message,error=null)}}
 fun flag(name:String,value:Boolean){if(name !in flagNames)return;if(!value&&name=="assistant_tools"&&executingSource=="Gemini proposal")execution?.cancel();if(!value&&name.startsWith("automation_")&&executingName in setOf("scroll_app","back_app"))execution?.cancel();store.setFlag(name,value);mutable.update{it.copy(flags=it.flags+(name to value))}}
 fun loadApps(activity:Activity){viewModelScope.launch{try{val result=withContext(Dispatchers.IO){AndroidTools(activity,store,mcp).apps()};mutable.update{it.copy(apps=result)}}catch(e:Exception){fail("Installed apps could not be queried.")}}}
 fun searchContacts(activity:Activity,query:String){val ticket=contactGate.begin();contactJob?.cancel();mutable.update{it.copy(contacts=emptyList())};contactJob=viewModelScope.launch{try{val matches=AndroidTools(activity,store,mcp).contacts(query);if(contactGate.current(ticket)&&androidx.core.content.ContextCompat.checkSelfPermission(activity,android.Manifest.permission.READ_CONTACTS)==android.content.pm.PackageManager.PERMISSION_GRANTED)mutable.update{it.copy(contacts=matches,error=null)}}catch(e:Exception){if(e is CancellationException)throw e;if(contactGate.current(ticket))fail("Contacts query failed or access was revoked. Recheck Contacts permission and retry manually.")}}}
 fun selectRecipient(contact:DeviceContact){try{store.selectRecipient(contact);mutable.update{it.copy(selected=contact,error=null,notice="Selected recipient saved locally for future previews only. No call/message authorized.")}}catch(e:Exception){fail("Could not save selected recipient. Check its name/number.")}}
 fun clearRecipient(){try{store.clearRecipient();mutable.update{it.copy(selected=null,error=null,notice="Selected recipient cleared locally.")}}catch(e:Exception){fail("Could not clear selected recipient.")}}
 fun saveMemory(id:String?,kind:String,label:String,value:String,lookup:String=""){viewModelScope.launch{try{require(store.flag("memory_enabled")){"Enable local memory first."};withContext(Dispatchers.IO){store.saveMemory(MemoryItem(id?:UUID.randomUUID().toString(),kind,label,value,lookup,"User saved/corrected on device"))};refresh();notice("Saved locally. Preferences are not model training.")}catch(e:Exception){fail("Memory could not be saved. Enable memory, check limits and remove any credentials from the value.")}}}
 fun deleteMemory(id:String){viewModelScope.launch{try{withContext(Dispatchers.IO){store.deleteMemory(id)};refresh();notice("Memory deleted from the local database. Previously sent provider context cannot be recalled.")}catch(e:Exception){fail("Could not delete memory. Stored data was preserved.")}}}
 fun propose(activity:Activity,action:ToolAction,source:String="User tools screen"){viewModelScope.launch{try{val runner=AndroidTools(activity,store,mcp);val task=withContext(Dispatchers.IO){ProposalFactory(store,runner::prepare).create(action,source)};refresh();notice(if(task.status==TaskStatus.NEEDS_APPROVAL)"Action prepared. Open Tasks to inspect and approve; nothing has executed." else task.detail)}catch(e:Exception){if(e is CancellationException)throw e;fail("Could not store this proposal. Review pending-task capacity and local storage; nothing executed.")}}}
 fun routeCommand(activity:Activity,text:String):Boolean {val action=parseUserCommand(text)?:return false;propose(activity,action,"Explicit user command");return true}
 fun approve(activity:Activity,id:String){if(execution?.isActive==true){fail("Another tool is executing. Cancel it first.");return};executingName=state.value.tasks.find{it.id==id}?.action?.name;executingSource=state.value.tasks.find{it.id==id}?.source;execution=viewModelScope.launch{mutable.update{it.copy(busy=true,error=null)};try{val runner=AndroidTools(activity,store,mcp);val result=withContext(Dispatchers.IO){TaskCoordinator(store,{runner.unlocked()},runner,{task->if(task.source=="Gemini proposal"&&!store.flag("assistant_tools"))ToolOutcome(TaskStatus.CANCELLED,"Gemini tool permission was revoked. Prepare a new request after explicit opt-in.")else null}).approve(id)};notice(result.detail.take(500))}catch(e:CancellationException){throw e}catch(e:Exception){fail("Tool status could not be updated. External outcome may be unknown; no automatic retry.")}finally{withContext(NonCancellable){refresh();mutable.update{it.copy(busy=false)}}}}}
 fun cancel(id:String){val task=state.value.tasks.find{it.id==id};if(task?.status==TaskStatus.EXECUTING)execution?.cancel()else viewModelScope.launch{try{withContext(Dispatchers.IO){pendingTaskStates.forEach{from->store.transition(id,from,TaskStatus.CANCELLED,"Cancelled by user before execution.")}};refresh()}catch(e:Exception){fail("Task cancellation could not be recorded. No execution was requested.")}}}
 fun clearFinishedTasks(){viewModelScope.launch{try{withContext(Dispatchers.IO){store.clearFinishedTasks()};refresh();notice("Finished task records removed. Pending/executing requests were preserved.")}catch(e:Exception){fail("Could not clear task records.")}}}
 fun stopExecution(){execution?.cancel()}
 fun saveWakeKey(value:String){try{store.saveSecret("porcupine",value.trim());mutable.update{it.copy(wakeKey=true)};notice("Picovoice credential encrypted on this device. Detector has not been tested.")}catch(e:Exception){fail("Could not securely save the Picovoice credential.")}}
 fun deleteWakeKey(){store.deleteSecret("porcupine");mutable.update{it.copy(wakeKey=false)}}
 fun saveServer(id:String?,name:String,url:String,token:String){if(executingName=="mcp_call")execution?.cancel();if(id!=null){probeEpoch[id]=UUID.randomUUID().toString();probes.remove(id)?.cancel();mutable.update{it.copy(tools=it.tools-id,connection=it.connection-id)}};viewModelScope.launch{try{require(name.isNotBlank()&&name.length<=100&&publicHttps(url));withContext(Dispatchers.IO){val existing=readServers(store);val selected=id?:UUID.randomUUID().toString();val old=existing.find{it.id==selected};require(old==null||old.endpoint==url||token.isNotBlank()){ "Enter a new credential when changing destination." };writeServers(store,existing.filterNot{it.id==selected}+McpServer(selected,name.trim(),url,false,if(old?.endpoint==url)old.allowed else emptySet()),selected,token.trim())};refresh();notice("MCP configuration saved, disabled and NOT TESTED. Test it, then explicitly allow tools.")}catch(e:Exception){fail("Use a trusted HTTPS MCP URL on port 443 without query, fragment or embedded credentials. Endpoint changes require a new token.")}}}
 fun serverEnabled(id:String,value:Boolean){if(!value&&executingName=="mcp_call")execution?.cancel();viewModelScope.launch{try{withContext(Dispatchers.IO){writeServers(store,readServers(store).map{if(it.id==id)it.copy(enabled=value)else it})};refresh()}catch(e:Exception){fail("Could not update MCP server. Existing data was preserved.")}}}
 fun allowTool(id:String,name:String,value:Boolean){if(!value&&executingName=="mcp_call")execution?.cancel();viewModelScope.launch{try{withContext(Dispatchers.IO){writeServers(store,readServers(store).map{if(it.id==id)it.copy(allowed=if(value)it.allowed+name else it.allowed-name)else it})};refresh()}catch(e:Exception){fail("Could not update tool permission.")}}}
 fun removeServer(id:String){if(executingName=="mcp_call")execution?.cancel();probeEpoch[id]=UUID.randomUUID().toString();probes.remove(id)?.cancel();viewModelScope.launch{try{withContext(Dispatchers.IO){writeServers(store,readServers(store).filterNot{it.id==id});store.deleteSecret("mcp_$id")};mutable.update{it.copy(tools=it.tools-id,connection=it.connection-id)};refresh()}catch(e:Exception){fail("Could not remove MCP configuration.")}}}
 fun testServer(server:McpServer){if(state.value.connection[server.id]=="TESTING")return;val ticket=UUID.randomUUID().toString();probeEpoch[server.id]=ticket;probes[server.id]=viewModelScope.launch{mutable.update{it.copy(connection=it.connection+(server.id to "TESTING"))};try{require(readServers(store).any{it.id==server.id&&it.endpoint==server.endpoint}){"Server configuration changed."};val token=if(store.secretPresent("mcp_${server.id}"))store.secret("mcp_${server.id}")else "";val tools=mcp.discover(server,token);if(probeEpoch[server.id]!=ticket||readServers(store).none{it.id==server.id&&it.endpoint==server.endpoint})return@launch;mutable.update{it.copy(tools=it.tools+(server.id to tools),connection=it.connection+(server.id to "CONNECTED — initialize and tools/list succeeded; no tool was executed"))}}catch(e:Exception){if(e is CancellationException)throw e;if(probeEpoch[server.id]!=ticket)return@launch;mutable.update{it.copy(connection=it.connection+(server.id to "FAILED — ${if(e is McpException)e.message else "Network, credential or protocol failure"}"))}}}}
 override fun onCleared(){execution?.cancel();contactGate.invalidate();contactJob?.cancel();probes.values.forEach{it.cancel()};mcp.close();val cleanScope=CoroutineScope(SupervisorJob()+Dispatchers.IO);cleanScope.launch{try{execution?.join();probes.values.toList().joinAll();store.close()}finally{cleanScope.cancel()}};super.onCleared()}
}
